// Map 4 only. Six byte-identical Map 1 samples; no award/save/physics writes.
export const MAP4_SAMPLE_EVENTS=Object.freeze({jump:'jump',spore:'spore',hurt:'hurt','projectile-hurt':'hurt','spike-hurt':'hurt','crusher-hurt':'hurt',clear:'clear'});
const IDS=['jump','spore','hurt','checkpoint','clear','button'];
export class Map4SampleAudio{
 constructor({factory=()=>new AudioContext(),fetcher=(...a)=>fetch(...a),hidden=()=>document.hidden}={}){this.factory=factory;this.fetcher=fetcher;this.isHidden=hidden;this.context=null;this.buffers=new Map;this.errors=new Set;this.active=new Set;this.enabled=true;this.paused=false;this.mapId=4;this.game=null;this.won=false;this.log=[];this.volume=.25;this.pending=null;this.ready=false;}
 async unlock(){if(!this.enabled)return;try{this.context??=this.factory();if(this.context.state==='suspended')await this.context.resume();this.pending??=Promise.all(IDS.map(async id=>{try{const response=await this.fetcher(new URL(`../audio/sfx/${id}-v1.mp3`,import.meta.url));if(!response.ok)throw Error(response.status);this.buffers.set(id,await this.context.decodeAudioData(await response.arrayBuffer()));}catch{this.errors.add(id);}})).then(()=>{this.ready=true;});await this.pending;}catch{}}
 handlesButton(g){return g.mapId===4&&this.buffers.has('button');}
 setEnabled(value){this.enabled=!!value;if(!this.enabled)this.stopAll();}
 stopAll(){for(const source of this.active){try{source.stop();}catch{}}this.active.clear();}
 updateGame(g){if(this.game!==g||(this.lastMode==='result'&&g.mode==='playing')){this.stopAll();this.won=false;this.game=g;}this.mapId=g.mapId;this.lastMode=g.mode;const paused=this.isHidden()||g.mode==='paused'||g.mapId!==4;if(paused&&!this.paused)this.stopAll();this.paused=paused;}
 play(id){if(!this.enabled||(this.paused&&id!=='button')||this.isHidden()||this.mapId!==4)return true;if(!this.buffers.has(id)||this.context?.state!=='running')return false;const now=this.context.currentTime;if(id==='button'&&now-(this.lastButton??-1)<.08)return true;if(id==='button')this.lastButton=now;let count=0;for(const a of this.active)if(a.sampleId===id)count++;if(count>=3)return true;const source=this.context.createBufferSource(),gain=this.context.createGain();source.buffer=this.buffers.get(id);source.loop=false;source.sampleId=id;gain.gain.value=this.volume;source.connect(gain);gain.connect(this.context.destination);source.onended=()=>this.active.delete(source);this.active.add(source);source.start();this.log.push({id,at:now});if(this.log.length>160)this.log.shift();return true;}
 handleEvent(event,g){this.updateGame(g);const id=event.startsWith('checkpoint-')?'checkpoint':MAP4_SAMPLE_EVENTS[event];if(!id)return false;if(event==='clear'){if(this.won)return true;const ok=this.play(id);if(ok)this.won=true;return ok;}return this.play(id);}
}
